using System.IO;
using System.Text;
using System.Windows.Threading;
using SentienceJP.Core;
using SentienceJP.Core.Payload;
using SentienceJP.Core.Platform;
using SentienceJP.Core.Steam;
using SentienceJP.Patcher.Services;

namespace SentienceJP.Patcher.Tests;

/// <summary>
/// テンポラリに作る偽のゲームフォルダ（Steam ライブラリ風の構成）・ログフォルダと、テスト用のペイロード。
/// 実ゲームのファイルは使わない。破棄時にフォルダごと削除する。
/// </summary>
internal sealed class FakeGameSetup : IDisposable
{
    /// <summary>元の plugins.js（RPGツクールMV の形式の合成データ）。</summary>
    public const string OriginalPluginsJs =
        "// Generated by RPG Maker.\r\n// Do not edit this file directly.\r\nvar $plugins =\r\n[\r\n{\"name\":\"Community_Basic\",\"status\":true,\"description\":\"\",\"parameters\":{}}\r\n];\r\n";

    /// <summary>偽のゲームフォルダとログフォルダを作る。</summary>
    public FakeGameSetup()
    {
        Root = Path.Combine(Path.GetTempPath(), "sentience_jp_vm_tests", Guid.NewGuid().ToString("N"));
        GameDirectory = Path.Combine(Root, "steamapps", "common", "Sentience");
        ManifestPath = Path.Combine(Root, "steamapps", $"appmanifest_{GameConstants.SteamAppId}.acf");
        LogDirectory = Path.Combine(Root, "logs");
        Directory.CreateDirectory(Path.Combine(GameDirectory, "www", "data"));
        Directory.CreateDirectory(Path.Combine(GameDirectory, "www", "js", "plugins"));
        File.WriteAllBytes(Path.Combine(GameDirectory, "nw.exe"), [0x4D, 0x5A]);
        File.WriteAllText(Path.Combine(GameDirectory, "www", "data", "System.json"), "{}");
        File.WriteAllText(Path.Combine(GameDirectory, "www", "js", "plugins.js"), OriginalPluginsJs, new UTF8Encoding(false));
        File.WriteAllText(
            ManifestPath,
            $"\"AppState\"\n{{\n\t\"appid\"\t\t\"{GameConstants.SteamAppId}\"\n\t\"name\"\t\t\"Sentience\"\n\t\"StateFlags\"\t\t\"4\"\n\t\"installdir\"\t\t\"Sentience\"\n\t\"buildid\"\t\t\"2476493\"\n}}\n");
    }

    /// <summary>このテスト用のフォルダ全体。</summary>
    public string Root { get; }

    /// <summary>偽のゲームフォルダ。</summary>
    public string GameDirectory { get; }

    /// <summary>偽の appmanifest のパス。</summary>
    public string ManifestPath { get; }

    /// <summary>ログフォルダ。</summary>
    public string LogDirectory { get; }

    /// <summary>検出したゲームの情報（起動時の検出結果の代わり）。</summary>
    public GameInstallation Installation =>
        new(GameDirectory, Root, ManifestPath, new AppManifest(GameConstants.SteamAppId, "Sentience", "Sentience", "2476493", 4));

    /// <summary>指定したバージョンのペイロード（内容は同じ 2 ファイル）を作る。</summary>
    /// <param name="patchVersion">パッチのバージョン。</param>
    public static PayloadBundle Payload(string patchVersion)
    {
        var plugin = Encoding.UTF8.GetBytes("/* SentienceJP test plugin */\n");
        var translation = Encoding.UTF8.GetBytes("{\"units\":{}}\n");
        var manifestJson =
            "{\"schema\":1," +
            $"\"patchVersion\":\"{patchVersion}\"," +
            "\"translationVersion\":\"test\"," +
            "\"pluginEntry\":{\"name\":\"SentienceJP\",\"status\":true,\"description\":\"test\",\"parameters\":{}}," +
            "\"files\":[" +
            $"{{\"path\":\"www/js/plugins/SentienceJP.js\",\"sha256\":\"{Hashing.Sha256Hex(plugin)}\",\"size\":{plugin.Length}}}," +
            $"{{\"path\":\"www/sentience_jp/translation.json\",\"sha256\":\"{Hashing.Sha256Hex(translation)}\",\"size\":{translation.Length}}}" +
            "]}";
        var manifest = PayloadManifestParser.Parse(Encoding.UTF8.GetBytes(manifestJson));
        var files = new Dictionary<string, byte[]>(StringComparer.Ordinal)
        {
            ["www/js/plugins/SentienceJP.js"] = plugin,
            ["www/sentience_jp/translation.json"] = translation,
        };
        return new PayloadBundle(manifest, files, "テスト用ペイロード");
    }

    /// <inheritdoc />
    public void Dispose()
    {
        if (Directory.Exists(Root))
        {
            Directory.Delete(Root, recursive: true);
        }
    }
}

/// <summary>
/// 呼び出しを記録する偽のダイアログ。確認（Confirm）の各呼び出しで任意の処理を差し込める
/// （確認ダイアログの表示中に、入れ子のメッセージループの中で別の操作が実行される状況の模擬に使う）。
/// </summary>
internal sealed class FakeDialogs : IDialogService
{
    private int _confirmCount;

    /// <summary>表示した内容の記録（"Info: …" などの形）。</summary>
    public List<string> Calls { get; } = [];

    /// <summary>確認の n 回目（1 から）に呼ぶ処理。戻り値が「はい」を選んだかになる（未設定なら「はい」）。</summary>
    public Func<int, string, bool>? OnConfirm { get; set; }

    /// <inheritdoc />
    public void ShowInfo(string message) => Calls.Add("Info: " + message);

    /// <inheritdoc />
    public void ShowWarning(string message) => Calls.Add("Warning: " + message);

    /// <inheritdoc />
    public void ShowError(string message) => Calls.Add("Error: " + message);

    /// <inheritdoc />
    public bool Confirm(string message, bool defaultToNo = false)
    {
        var count = ++_confirmCount;
        Calls.Add($"Confirm#{count}: " + message);
        return OnConfirm?.Invoke(count, message) ?? true;
    }
}

/// <summary>決まった結果を返す偽のプロセス確認。</summary>
/// <param name="state">返す起動状況。</param>
internal sealed class FakeProcessChecker(GameProcessState state) : IGameProcessChecker
{
    /// <inheritdoc />
    public GameProcessState Check(string gameDirectory) => state;
}

/// <summary>
/// STA スレッドで Dispatcher を回し、その上で非同期の本体を実行する（WPF の UI スレッドの模擬）。
/// AsyncRelayCommand（async void）から漏れた例外は、実際のアプリと同じく Dispatcher の未処理例外として集めて返す。
/// </summary>
internal static class DispatcherRunner
{
    /// <summary>本体を UI スレッドの模擬の上で実行し、終わるまで待つ。</summary>
    /// <param name="body">実行する非同期の本体。</param>
    /// <param name="timeoutSeconds">待つ上限の秒数。</param>
    /// <returns>Dispatcher の未処理例外（無ければ空）。</returns>
    public static List<Exception> Run(Func<Task> body, int timeoutSeconds = 60)
    {
        var unhandled = new List<Exception>();
        Exception? failure = null;
        var thread = new Thread(() =>
        {
            var dispatcher = Dispatcher.CurrentDispatcher;
            SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(dispatcher));
            dispatcher.UnhandledException += (_, e) =>
            {
                unhandled.Add(e.Exception);
                e.Handled = true;
            };
            dispatcher.BeginInvoke(new Action(async () =>
            {
                try
                {
                    await body();
                }
                catch (Exception ex)
                {
                    failure = ex;
                }
                finally
                {
                    dispatcher.BeginInvokeShutdown(DispatcherPriority.Background);
                }
            }));
            Dispatcher.Run();
        });
        thread.SetApartmentState(ApartmentState.STA);
        thread.Start();
        if (!thread.Join(TimeSpan.FromSeconds(timeoutSeconds)))
        {
            throw new TimeoutException("Dispatcher の処理が時間内に終わりませんでした。");
        }

        if (failure is not null)
        {
            throw new InvalidOperationException($"テストの本体が失敗しました: {failure.Message}", failure);
        }

        return unhandled;
    }

    /// <summary>条件が満たされるまで、Dispatcher を回しながら待つ。</summary>
    /// <param name="condition">待つ条件。</param>
    /// <param name="timeoutMilliseconds">待つ上限のミリ秒。</param>
    public static async Task WaitUntil(Func<bool> condition, int timeoutMilliseconds = 20000)
    {
        var start = Environment.TickCount64;
        while (!condition())
        {
            if (Environment.TickCount64 - start > timeoutMilliseconds)
            {
                throw new TimeoutException("条件が時間内に満たされませんでした。");
            }

            await Task.Delay(10);
        }
    }
}
